def annotations(kit, stack):
    a = {}
    a['p_AlphaClipThreshold'] = bpy.props.FloatProperty(name='Alpha Clip Threshold', description='镂空阈值:透明度低于它的像素被丢掉,需要打开「Use Alpha Test」;调大镂空更多。\n_AlphaClipThreshold', default=0.5, min=0.0, max=1.0, update=kit.writer(stack, '_AlphaClipThreshold'))
    a['p_UseAlphaTest'] = bpy.props.BoolProperty(name='Use Alpha Test', description='镂空开关:打开后透明度低于「Alpha Clip Threshold」的像素被直接丢掉,边缘变成硬边,不再是半透明渐变。\n_UseAlphaTest', default=False, update=kit.writer(stack, '_UseAlphaTest'))
    a['p_IgnorePostExposure'] = bpy.props.BoolProperty(name='Ignore Post Exposure', description='不受自动曝光影响:打开后特效颜色会乘上曝光补偿,画面曝光变化时特效亮度保持不变;关闭则特效和场景一起随曝光变亮变暗。\n_IgnorePostExposure', default=True, update=kit.writer(stack, '_IgnorePostExposure'))
    a['p_CullMode'] = bpy.props.FloatProperty(name='Cull Mode', description='渲染模型的哪一面:0 双面,1 只画背面,2 只画正面(数值同引擎的剔除模式)。特效面片常选双面。\n_CullMode', default=2.0, update=kit.writer(stack, '_CullMode'))
    a['p_ExposureWithMiscParams'] = bpy.props.FloatVectorProperty(name='Exposure (y = post exposure)', description='引擎全局曝光参数,由场景自动写入,一般不用手调。\nX: 没有用到。\nY: 后曝光倍率:「不受自动曝光影响」的特效会乘它。\nZ: 没有用到。\nW: 没有用到。\n_ExposureWithMiscParams', size=4, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_ExposureWithMiscParams'))
    a['p_VFXParams1'] = bpy.props.FloatVectorProperty(name='VFX Grade (rgb = tint, w = saturation)', description='引擎全局的最终调色参数,由场景自动写入,一般不用手调。\nX: 整体染色的红分量(1 = 不变)。\nY: 整体染色的绿分量(1 = 不变)。\nZ: 整体染色的蓝分量(1 = 不变)。\nW: 整体饱和度:1 = 不变,0 = 灰度。\n_VFXParams1', size=4, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_VFXParams1'))
    a['p_VFXParams0'] = bpy.props.FloatVectorProperty(name='VFX Params0 (xyz = 角色位, w = 时间)', description='引擎全局的特效参数,由场景自动写入,一般不用手调。\nX: 角色的世界位置 X(亮心、全局显隐用来当中心)。\nY: 角色的世界位置 Y。\nZ: 角色的世界位置 Z。\nW: 时间(秒):所有「按时间」的滚动、呼吸、扫描都靠它。\n_VFXParams0', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_VFXParams0'))
    a['p_GlobalsFresnelColor'] = bpy.props.FloatVectorProperty(name='Globals Fresnel Color', description='引擎全局的边缘光颜色:由游戏写入,材质自己不用调。\nX: 颜色红分量。\nY: 颜色绿分量。\nZ: 颜色蓝分量。\nW: 混入的比例。\n_GlobalsFresnelColor', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_GlobalsFresnelColor'))
    a['punity_Float4x5_Param0'] = bpy.props.FloatVectorProperty(name='Per-Draw Instance Data 0', description='引擎逐绘制传来的实例数据(不是手调的参数):体积光束只用 X,光束整体乘(1 − X)。\nX: 光束整体淡出量:0 = 正常,1 = 完全消失。\nY: 没有用到。\nZ: 没有用到。\nW: 没有用到。\nunity_Float4x5_Param0', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, 'unity_Float4x5_Param0'))
    a['p_TintColor'] = bpy.props.FloatVectorProperty(name='Tint Color', description='染色:乘在特效主图上,白色 = 不改变;想让同一张图换成别的颜色就调它。\nA: 整体不透明度系数,再乘上「Tint Color Alpha」。\n_TintColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_TintColor'))
    a['p_TintColorIntensity'] = bpy.props.FloatProperty(name='Tint Color Intensity', description='颜色亮度倍率(0 – 100):大于 1 让特效发出超过画面白点的强光,配合后处理泛光会出光晕。\n_TintColorIntensity', default=1.0, min=0.0, max=100.0, update=kit.writer(stack, '_TintColorIntensity'))
    a['p_TintColorAlpha'] = bpy.props.FloatProperty(name='Tint Color Alpha', description='不透明度倍率(0 – 10):大于 1 能把偏淡的图补得更实,但仍会被限制在最大不透明。\n_TintColorAlpha', default=1.0, min=0.0, max=10.0, update=kit.writer(stack, '_TintColorAlpha'))
    a['p_DisableVertColor'] = bpy.props.BoolProperty(name='Disable Vert Color', description='忽略顶点色:关闭时模型或粒子的顶点颜色会乘进特效的颜色和透明度(粒子系统常靠它做淡入淡出);打开则完全不受顶点色影响。\n_DisableVertColor', default=False, update=kit.writer(stack, '_DisableVertColor'))
    a['p_BlendMode'] = bpy.props.FloatProperty(name='Blend Mode (0=Alpha 1=Additive 2=Premultiplied)', description='混合方式:0 = Alpha 普通透明,按透明度叠在后面画面上;1 = Additive 叠加发光,颜色先乘透明度再加到画面上,越叠越亮,适合火花光效;2 = Premultiplied 预乘透明,适合已经乘过透明度的贴图,多用于烟雾、火焰。\n_BlendMode', default=0.0, update=kit.writer(stack, '_BlendMode'))
    a['p_IsSceneEffect'] = bpy.props.BoolProperty(name='Scene Effect (color grade)', description='场景特效:打开后特效颜色再过一遍场景的最终调色(整体染色与饱和度,由引擎全局参数给),让特效和场景的色调一致;关闭则保持特效自己的颜色。\n_IsSceneEffect', default=False, update=kit.writer(stack, '_IsSceneEffect'))
    a['p_UseMainTexAsAlpha'] = bpy.props.BoolProperty(name='Use MainTex As Alpha', description='主图 R 通道当透明度:打开后主图只用 R(灰度)决定哪里显示,颜色不再取自主图而由「Tint Color」决定;适合灰度的流光、光斑图案。\n_UseMainTexAsAlpha', default=False, update=kit.writer(stack, '_UseMainTexAsAlpha'))
    a['p_MainTexUVSpeed'] = bpy.props.FloatVectorProperty(name='MainTex UV Speed', description='主图的 UV 滚动速度(UV 单位,正负决定方向)。前两个数按时间滚动,后两个数按粒子自定义数据滚动(需要打开「In Particle」,只有部分特效着色器用到)。\nX: 按时间沿 U(横向)滚动:每秒滚动多少。\nY: 按时间沿 V(纵向)滚动:每秒滚动多少。\nZ: 按粒子自定义数据 Custom1.X 沿 U 滚动:Custom1.X 每增加 1 滚动多少。\nW: 按粒子自定义数据 Custom1.X 沿 V 滚动:Custom1.X 每增加 1 滚动多少。\n_MainTexUVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_MainTexUVSpeed'))
    a['p_MainTexUVWeights'] = bpy.props.FloatVectorProperty(name='MainTex UV Weights', description='主图用哪一套 UV:最终 UV = 第一套 UV × X + 第二套(粒子)UV × Y + 屏幕 UV × W。默认 (1, 0, 0, 0) = 只用第一套 UV。\nX: 第一套 UV(UV0)的权重。\nY: 第二套 UV(粒子 UV)的权重。\nZ: 没有用到。\nW: 屏幕 UV 的权重(需要打开「Use Screen UV」)。\n_MainTexUVWeights', size=4, default=(1.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_MainTexUVWeights'))
    a['p_MainTexUseDisturb'] = bpy.props.BoolProperty(name='MainTex Use Disturb', description='主图受扰动的程度:0 = 不受扰动影响,1 = 完全跟着扰动图扭曲。\n_MainTexUseDisturb', default=False, update=kit.writer(stack, '_MainTexUseDisturb'))
    a['p_MainTexUVRotateMat'] = bpy.props.FloatVectorProperty(name='MainTex UV Rotate Mat', description='主图的 UV 旋转(绕图的中心):四个数是 2×2 旋转矩阵,不是角度。要转 θ 度就填 (cosθ, sinθ, −sinθ, cosθ);默认 (1, 0, 0, 1) = 不旋转。\nX: 新 U 里 U 的系数(旋转时 = cosθ)。\nY: 新 V 里 U 的系数(旋转时 = sinθ)。\nZ: 新 U 里 V 的系数(旋转时 = −sinθ)。\nW: 新 V 里 V 的系数(旋转时 = cosθ)。\n_MainTexUVRotateMat', size=4, default=(1.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_MainTexUVRotateMat'))
    a['p_InParticle'] = bpy.props.BoolProperty(name='In Particle', description='用在粒子上:打开表示材质挂在粒子系统里,可以读粒子第二套 UV 里的自定义数据(Custom1.X、Custom1.Y)去驱动「按自定义数据」的滚动;关闭则这些自定义数据当 0,用于普通模型。\n_InParticle', default=False, update=kit.writer(stack, '_InParticle'))
    a['p_RowsColumns'] = bpy.props.FloatVectorProperty(name='Frame Rows/Columns', description='序列帧图集的行列数(界面特效帧):X = 行数,Y = 列数,其余两个数不用。\nX: 行数(纵向格子数)。\nY: 列数(横向格子数)。\nZ: 没有用到。\nW: 没有用到。\n_RowsColumns', size=4, default=(1.0, 1.0, 0.0, 0.0,), update=kit.writer(stack, '_RowsColumns'))
    a['p_Frame'] = bpy.props.FloatProperty(name='Frame Index', description='当前帧号(界面特效帧):从 1 开始数,先横向后纵向,超出范围夹到首尾帧。\n_Frame', default=1.0, update=kit.writer(stack, '_Frame'))
    a['p_ScaleOffset'] = bpy.props.FloatVectorProperty(name='Frame Scale/Offset', description='帧内缩放与平移(界面特效帧):X、Y 把每一格里的画面放大,Z、W 在格内平移。\nX: 格内横向放大倍数:越大画面越被放大,小于 1 缩小。\nY: 格内纵向放大倍数:越大画面越被放大,小于 1 缩小。\nZ: 格内横向平移(占单格宽度的比例),正值把画面往右推。\nW: 格内纵向平移(占单格高度的比例),正值把画面往上推。\n_ScaleOffset', size=4, default=(1.0, 1.0, 0.0, 0.0,), update=kit.writer(stack, '_ScaleOffset'))
    a['p_CutsceneBaseColor'] = bpy.props.FloatVectorProperty(name='Cutscene Base Color', description='过场光带基础色(HDR):RGB 是光(或暗化)的颜色,A 乘进整体不透明度。\n_CutsceneBaseColor', size=4, subtype='COLOR_GAMMA', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_CutsceneBaseColor'))
    a['p_LightRange1'] = bpy.props.FloatProperty(name='Light Range 1', description='光带渐变的外端位置(0 – 1):光强在坐标(1 − 这个值)处为 0。坐标:纵向模式 = 面片的 V(下 0 上 1),径向模式 = 到面片中心的距离(中心 0 边缘 1)。\n_LightRange1', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_LightRange1'))
    a['p_LightRange2'] = bpy.props.FloatProperty(name='Light Range 2', description='光带渐变的内端位置(0 – 1):光强在坐标(1 − 这个值)处达到最大。坐标:纵向模式 = 面片的 V(下 0 上 1),径向模式 = 到面片中心的距离(中心 0 边缘 1)。\n_LightRange2', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_LightRange2'))
    a['p_LeftFadeRange'] = bpy.props.FloatProperty(name='Left Fade Range', description='光带左边缘淡出宽度(UV 单位):从左边缘向内这么宽的范围由透明渐变到不透明。\n_LeftFadeRange', default=0.1, update=kit.writer(stack, '_LeftFadeRange'))
    a['p_RightFadeRange'] = bpy.props.FloatProperty(name='Right Fade Range', description='光带右边缘淡出宽度(UV 单位):从右边缘向内这么宽的范围由透明渐变到不透明。\n_RightFadeRange', default=0.1, update=kit.writer(stack, '_RightFadeRange'))
    a['p_ColorOption'] = bpy.props.BoolProperty(name='Color Option (亮/暗)', description='亮/暗模式:关 = 亮光模式(颜色加亮,用「Light Intensity」),开 = 暗化模式(在白与基础色之间压暗,用「Dark Intensity」)。\n_ColorOption', default=False, update=kit.writer(stack, '_ColorOption'))
    a['p_ShapeOption'] = bpy.props.BoolProperty(name='Shape Option (纵向/径向)', description='光带形状:关 = 纵向(沿面片的 V 方向渐变),开 = 径向(从面片中心向边缘渐变)。\n_ShapeOption', default=False, update=kit.writer(stack, '_ShapeOption'))
    a['p_DepthFadePosition'] = bpy.props.FloatProperty(name='Depth Fade Position', description='近处淡出的分界距离(到相机的距离,世界单位):比它更近的部分按「Near Fade Intensity」衰减,比它远出「Depth Fade Range」以上的部分保持不变,中间渐变。\n_DepthFadePosition', default=0.0, update=kit.writer(stack, '_DepthFadePosition'))
    a['p_NearFadeIntensity'] = bpy.props.FloatProperty(name='Near Fade Intensity', description='近处淡出时保留的强度:1 = 近处不衰减,0 = 近处完全消失。\n_NearFadeIntensity', default=1.0, update=kit.writer(stack, '_NearFadeIntensity'))
    a['p_DepthFadeRange'] = bpy.props.FloatProperty(name='Depth Fade Range', description='近处淡出的过渡带宽度(世界单位)。\n_DepthFadeRange', default=1.0, update=kit.writer(stack, '_DepthFadeRange'))
    a['p_LightIntensity'] = bpy.props.FloatProperty(name='Light Intensity', description='亮光模式下光带的强度倍率(「Color Option」关时使用)。\n_LightIntensity', default=1.0, update=kit.writer(stack, '_LightIntensity'))
    a['p_DarkIntensity'] = bpy.props.FloatProperty(name='Dark Intensity', description='暗化模式下光带的强度倍率(「Color Option」开时使用)。\n_DarkIntensity', default=1.0, update=kit.writer(stack, '_DarkIntensity'))
    a['p_EnableuseInvertFade'] = bpy.props.BoolProperty(name='Use Invert Fade', description='反向淡出:打开后近远互换——近处保持原样,远处按「Near Fade Intensity」衰减。\n_EnableuseInvertFade', default=False, update=kit.writer(stack, '_EnableuseInvertFade'))
    a['p_RainColor'] = bpy.props.FloatVectorProperty(name='Rain Color', description='雨条颜色(HDR,纯色):RGB 是雨的颜色,A 乘进不透明度。\n_RainColor', size=4, subtype='COLOR_GAMMA', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_RainColor'))
    a['p_RainTex0_ST'] = bpy.props.FloatVectorProperty(name='RainTex0 Tiling/Offset', description='雨图的平铺与强度:X、Y 是雨图横向、纵向的平铺倍数,Z、W 决定不透明度 = Z + W × (雨图 R × 2 − 1)。\nX: 雨图横向(U)平铺倍数。\nY: 雨图纵向(V)平铺倍数。\nZ: 雨的基础不透明度(雨图为 0.5 灰时的值)。\nW: 雨图对不透明度的起伏幅度,越大雨条明暗越分明。\n_RainTex0_ST', size=4, default=(1.0, 1.0, 0.0, 1.0,), update=kit.writer(stack, '_RainTex0_ST'))
    a['p_DecalBaseColor'] = bpy.props.FloatVectorProperty(name='Decal Base Color', description='贴花基础色(HDR):贴花的颜色(RGB)与不透明度(A,还要乘「Tint Color Alpha」),再乘主图与遮罩;RGB 超过 1 会发光。\n_DecalBaseColor', size=4, subtype='COLOR_GAMMA', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_DecalBaseColor'))
    a['p_EdgeFadeX'] = bpy.props.FloatProperty(name='Decal Edge Fade X', description='贴花盒左右(X)边缘淡出的起点(0 – 0.5,占盒宽比例):从盒中心算 0.5 − 这个值处开始变淡,越大贴花在左右边缘收得越早;0 = 从盒边开始。\n_EdgeFadeX', default=0.0, min=0.0, max=0.5, update=kit.writer(stack, '_EdgeFadeX'))
    a['p_EdgeFadeZ'] = bpy.props.FloatProperty(name='Decal Edge Fade Z', description='贴花盒前后(Z)边缘淡出的起点(0 – 0.5,占盒宽比例):从盒中心算 0.5 − 这个值处开始变淡,越大贴花在前后边缘收得越早;0 = 从盒边开始。\n_EdgeFadeZ', default=0.0, min=0.0, max=0.5, update=kit.writer(stack, '_EdgeFadeZ'))
