    a['p_DisturbUVRotateMat1'] = bpy.props.FloatVectorProperty(name='Disturb1 UV Rotate Mat', description='扰动图的 UV 旋转(绕图的中心):四个数是 2×2 旋转矩阵,不是角度。要转 θ 度就填 (cosθ, sinθ, −sinθ, cosθ);默认 (1, 0, 0, 1) = 不旋转。\nX: 新 U 里 U 的系数(旋转时 = cosθ)。\nY: 新 V 里 U 的系数(旋转时 = sinθ)。\nZ: 新 U 里 V 的系数(旋转时 = −sinθ)。\nW: 新 V 里 V 的系数(旋转时 = cosθ)。\n_DisturbUVRotateMat1', size=4, default=(1.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_DisturbUVRotateMat1'))
