    a['p_BlendTexUseDisturb'] = bpy.props.FloatProperty(name='BlendTex Use Disturb', description='混合图受扰动的程度:0 = 不受扰动影响,1 = 完全跟着扰动图扭曲。\n_BlendTexUseDisturb', default=0.0, update=kit.writer(stack, '_BlendTexUseDisturb'))
    a['p_DisturbUVWeights1'] = bpy.props.FloatVectorProperty(name='Disturb1 UV Weights', description='扰动图用哪一套 UV:最终 UV = 第一套 UV × X + 第二套(粒子)UV × Y + 屏幕 UV × W。默认 (1, 0, 0, 0) = 只用第一套。\nX: 第一套 UV(UV0)的权重。\nY: 第二套 UV(粒子 UV)的权重。\nZ: 没有用到。\nW: 屏幕 UV 的权重(需要打开「Use Screen UV」)。\n_DisturbUVWeights1', size=4, default=(1.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_DisturbUVWeights1'))
    a['p_BlendDisableVertColor'] = bpy.props.BoolProperty(name='BlendTex Disable Vertex Color', description='混合图忽略顶点色:打开后混合层的颜色不乘模型或粒子的顶点颜色。\n_BlendDisableVertColor', default=False, update=kit.writer(stack, '_BlendDisableVertColor'))
    a['p_InkSimulationWorldToUV'] = bpy.props.FloatVectorProperty(name='Ink Simulation World To UV', description='墨水模拟图和世界坐标的对应关系:由引擎自动写入,不用手调。\nX: 模拟图覆盖范围在世界 X 方向的偏移。\nY: 没有用到。\nZ: 模拟图覆盖范围在世界 Z 方向的偏移。\nW: 世界坐标到模拟图 UV 的缩放。\n_InkSimulationWorldToUV', size=4, default=(0.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_InkSimulationWorldToUV'))
    a['p_MaskTexUseInkSimulation'] = bpy.props.BoolProperty(name='MaskTex Use Ink Simulation', description='遮罩跟着墨水扰动:打开后墨水扩散处遮罩图的 UV 也被推歪。\n_MaskTexUseInkSimulation', default=False, update=kit.writer(stack, '_MaskTexUseInkSimulation'))
    a['p_DisturbTex1UseInkSimulation'] = bpy.props.BoolProperty(name='DisturbTex1 Use Ink Simulation', description='扰动图跟着墨水扰动:打开后墨水扩散处扰动图的 UV 也被推歪。\n_DisturbTex1UseInkSimulation', default=False, update=kit.writer(stack, '_DisturbTex1UseInkSimulation'))
    a['p_DitherTilling'] = bpy.props.FloatProperty(name='Dither Tilling', description='抖动透明的网点密度:越大屏幕网点越细密。\n_DitherTilling', default=1.0, update=kit.writer(stack, '_DitherTilling'))
