    a['p_DirSpecularStrength'] = bpy.props.FloatProperty(name='Dir Specular Strength', description='主光高光强度(水面):乘在太阳直射产生的高光上,0 = 没有直射高光。\n_DirSpecularStrength', default=0.0, update=kit.writer(stack, '_DirSpecularStrength'))
    a['p_FresnelStrength'] = bpy.props.FloatProperty(name='Fresnel Strength', description='菲涅尔强度(指数,水面):配合「Use Fresnel As Opacity」,不透明度乘(法线·视线)的这个次方——正对相机处不变,越靠边缘越透明,数值越大边缘透明得越多。\n_FresnelStrength', default=1.0, update=kit.writer(stack, '_FresnelStrength'))
    a['p_IndirectSaturation'] = bpy.props.FloatProperty(name='Indirect Saturation', description='间接光饱和度(0 – 1,水面):0 = 环境间接光变成灰色、只留亮度;1 = 保持原本的颜色。\n_IndirectSaturation', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_IndirectSaturation'))
    a['p_UseFresnelAsOpacity'] = bpy.props.BoolProperty(name='Use Fresnel As Opacity', description='用菲涅尔当不透明度(水面):打开后不透明度乘(法线·视线)^「Fresnel Strength」,水面边缘变透明、正对相机处保持原样。\n_UseFresnelAsOpacity', default=False, update=kit.writer(stack, '_UseFresnelAsOpacity'))
    a['p_UseVertexColorAsOpacity'] = bpy.props.BoolProperty(name='Use Vertex Color As Opacity', description='用顶点色当不透明度(水面):打开后不透明度乘顶点色 A,次表面强度乘顶点色 R,可以在建模里刷出水面哪里淡出、哪里透光。\n_UseVertexColorAsOpacity', default=False, update=kit.writer(stack, '_UseVertexColorAsOpacity'))
    a['p_WaterRandomUV'] = bpy.props.BoolProperty(name='Water Random UV', description='水面随机 UV:打开后每个物体的贴图按它的世界位置错开一个随机偏移(并略微拉伸),同一批水面不会长得一模一样。\n_WaterRandomUV', default=False, update=kit.writer(stack, '_WaterRandomUV'))
    a['p_RefractThickness'] = bpy.props.FloatProperty(name='Refract Thickness', description='折射厚度(水面):折射把背后画面推歪的距离,越大扭曲越明显;0 = 没有折射扭曲。\n_RefractThickness', default=0.0, update=kit.writer(stack, '_RefractThickness'))
    a['p_Specular'] = bpy.props.FloatProperty(name='Specular', description='高光反射率(0 – 1,水面):基础反射率 = 0.08 × 这个值,0 = 没有高光反射。\n_Specular', default=0.5, min=0.0, max=1.0, update=kit.writer(stack, '_Specular'))
    a['p_AbsorptionRange'] = bpy.props.FloatProperty(name='Absorption Range', description='吸收范围(六向烟雾):光在烟雾里能累积的亮度上限,上限 = (值 + 0.32) × 1.47。数值越大,烟雾最亮处越亮、越不容易被截平;数值小则亮部被压平。\n_AbsorptionRange', default=1.0, update=kit.writer(stack, '_AbsorptionRange'))
    a['p_EnvLightSaturation'] = bpy.props.FloatProperty(name='Env Light Saturation', description='环境光饱和度(0 – 1,六向烟雾):0 = 环境光变成灰色、只留亮度;1 = 保持环境光原本的颜色。\n_EnvLightSaturation', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_EnvLightSaturation'))
    a['p_LightMapUVRotate'] = bpy.props.FloatProperty(name='Lightmap UV Rotate (度)', description='光照图 UV 旋转(度,绕图的中心):两张六向光照图一起转。\n_LightMapUVRotate', default=0.0, update=kit.writer(stack, '_LightMapUVRotate'))
    a['p_LightMapUVSpeed'] = bpy.props.FloatVectorProperty(name='Lightmap UV Speed', description='光照图的 UV 滚动速度(UV 单位,正负决定方向)。前两个数按时间滚动,后两个数按粒子自定义数据 Custom1.X 滚动(需要打开「In Particle」)。\nX: 按时间沿 U(横向)滚动:每秒滚动多少。\nY: 按时间沿 V(纵向)滚动:每秒滚动多少。\nZ: 按粒子自定义数据 Custom1.X 沿 U 滚动:Custom1.X 每增加 1 滚动多少。\nW: 按粒子自定义数据 Custom1.X 沿 V 滚动:Custom1.X 每增加 1 滚动多少。\n_LightMapUVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_LightMapUVSpeed'))
