    a['p_Bi_Refract'] = bpy.props.FloatProperty(name='Bi Refract', description='双向折射:0 时折射只往一个方向推,1 时变成 −1 到 1,灰色处不推,偏亮偏暗分别往相反方向推。\n_Bi_Refract', default=0.0, update=kit.writer(stack, '_Bi_Refract'))
