    a['p_DisturbUVSpeed1'] = bpy.props.FloatVectorProperty(name='Disturb1 UV Speed', description='扰动图的 UV 滚动速度(UV 单位)。前两个数按时间滚动,后两个数按粒子自定义数据 Custom1.Y 滚动。\nX: 按时间沿 U(横向)滚动:每秒滚动多少。\nY: 按时间沿 V(纵向)滚动:每秒滚动多少。\nZ: 按粒子自定义数据 Custom1.Y 沿 U 滚动。\nW: 按粒子自定义数据 Custom1.Y 沿 V 滚动。\n_DisturbUVSpeed1', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_DisturbUVSpeed1'))
    a['p_DisturbUVSpeed2'] = bpy.props.FloatVectorProperty(name='Disturb2 UV Speed', description='第二张扰动图的 UV 滚动速度(UV 单位,只用前两个数)。\nX: 沿 U 每秒滚动多少。\nY: 沿 V 每秒滚动多少。\nZ: 没有用到。\nW: 没有用到。\n_DisturbUVSpeed2', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_DisturbUVSpeed2'))
    a['p_DisturbUIntensity2'] = bpy.props.FloatProperty(name='Disturb2 U Intensity', description='第二张扰动图在 U(横向)的强度。\n_DisturbUIntensity2', default=0.0, update=kit.writer(stack, '_DisturbUIntensity2'))
    a['p_DisturbVIntensity2'] = bpy.props.FloatProperty(name='Disturb2 V Intensity', description='第二张扰动图在 V(纵向)的强度。\n_DisturbVIntensity2', default=0.0, update=kit.writer(stack, '_DisturbVIntensity2'))
    a['p_DisturbTex2Normal'] = bpy.props.BoolProperty(name='Disturb2 Is Normal', description='第二张扰动图当法线用:打开后读法线通道,0.5 灰 = 不推。\n_DisturbTex2Normal', default=False, update=kit.writer(stack, '_DisturbTex2Normal'))
    a['p_WeightTexUVSpeed'] = bpy.props.FloatVectorProperty(name='WeightTex UV Speed', description='权重图的 UV 滚动速度(UV 单位,正负决定方向)。前两个数按时间滚动,后两个数按粒子自定义数据 Custom1.X 滚动(需要打开「In Particle」)。\nX: 按时间沿 U(横向)滚动:每秒滚动多少。\nY: 按时间沿 V(纵向)滚动:每秒滚动多少。\nZ: 按粒子自定义数据 Custom1.X 沿 U 滚动:Custom1.X 每增加 1 滚动多少。\nW: 按粒子自定义数据 Custom1.X 沿 V 滚动:Custom1.X 每增加 1 滚动多少。\n_WeightTexUVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_WeightTexUVSpeed'))
    a['p_WeightTexUVRotate'] = bpy.props.FloatProperty(name='WeightTex UV Rotate (度)', description='权重图 UV 旋转(度,绕图的中心)。\n_WeightTexUVRotate', default=0.0, update=kit.writer(stack, '_WeightTexUVRotate'))
    a['p_B_autoPlayback'] = bpy.props.BoolProperty(name='Auto Playback', description='序列帧自动播放:打开后按「Playback Speed」自动一帧一帧播放;关闭则停在「Display Frame」指定的那一帧。\n_B_autoPlayback', default=False, update=kit.writer(stack, '_B_autoPlayback'))
    a['p_GameTimeAtFirstFrame'] = bpy.props.FloatProperty(name='Game Time At First Frame', description='序列帧开始播放时的游戏时间(秒):用来让每个特效从自己的第 0 帧开始播,一般由游戏写入。\n_GameTimeAtFirstFrame', default=0.0, update=kit.writer(stack, '_GameTimeAtFirstFrame'))
    a['p_DisplayFrame'] = bpy.props.FloatProperty(name='Display Frame', description='手动指定显示的帧号:只在关闭自动播放时用,可以给它打关键帧控制播放进度。\n_DisplayFrame', default=0.0, update=kit.writer(stack, '_DisplayFrame'))
    a['p_PlaybackSpeed'] = bpy.props.FloatProperty(name='Playback Speed', description='序列帧的播放速度倍率:1 = 原速,2 = 两倍速,0 = 暂停。\n_PlaybackSpeed', default=0.0, update=kit.writer(stack, '_PlaybackSpeed'))
    a['p_LightMapFPS'] = bpy.props.FloatProperty(name='LightMap FPS', description='光照图序列帧速度(帧/秒):光照图是序列帧图集时按这个速度播放,行列数见「Sequence Frame Size」,需要打开序列帧;0 = 停在第一帧。\n_LightMapFPS', default=0.0, update=kit.writer(stack, '_LightMapFPS'))
    a['p_SequenceFrameSize'] = bpy.props.FloatVectorProperty(name='Sequence Frame Size (xy)', description='序列帧图集的行列数(只用前两个数)。\nX: 图集有几列。\nY: 图集有几行。\nZ: 没有用到。\nW: 没有用到。\n_SequenceFrameSize', size=4, default=(1.0, 1.0, 0.0, 0.0,), update=kit.writer(stack, '_SequenceFrameSize'))
    a['p_RBIntensity'] = bpy.props.FloatProperty(name='RBOffset Intensity', description='色差强度(0 – 1):0 = 没有色差,1 = 红蓝(或三色)通道完全按偏移错开。\n_RBIntensity', default=0.0, update=kit.writer(stack, '_RBIntensity'))
    a['p_RBOffset'] = bpy.props.FloatVectorProperty(name='RBOffset', description='色差的偏移量(只用前两个数):把被折射的画面按这个偏移再取一份,按颜色掩码混回,做出红蓝错位的色散。\nX: 横向偏移(单位约 0.01 屏幕宽)。\nY: 纵向偏移(单位约 0.01 屏幕高)。\nZ: 没有用到。\nW: 没有用到。\n_RBOffset', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_RBOffset'))
    a['p_RBMainColorMask'] = bpy.props.FloatVectorProperty(name='Main Color Mask', description='色差里「不偏移那一份」保留哪些颜色通道:默认红色 = 红通道不偏移,蓝绿通道由偏移的那份提供。\n_RBMainColorMask', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_RBMainColorMask'))
    a['p_RBOffsetColorMask'] = bpy.props.FloatVectorProperty(name='RBOffset Color Mask', description='色差里「偏移那一份」保留哪些颜色通道:默认青色 = 绿蓝通道取偏移后的画面。\n_RBOffsetColorMask', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(0.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_RBOffsetColorMask'))
    a['p_RBOffset1ColorMask'] = bpy.props.FloatVectorProperty(name='RBOffset1 Color Mask', description='三色色差里第一份偏移保留的颜色通道:默认绿色。\n_RBOffset1ColorMask', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(0.0, 1.0, 0.0, 1.0,), update=kit.writer(stack, '_RBOffset1ColorMask'))
    a['p_RBOffset2ColorMask'] = bpy.props.FloatVectorProperty(name='RBOffset2 Color Mask', description='三色色差里第二份偏移保留的颜色通道:默认蓝色。\n_RBOffset2ColorMask', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(0.0, 0.0, 1.0, 1.0,), update=kit.writer(stack, '_RBOffset2ColorMask'))
    a['p_UseMainTexAsMask'] = bpy.props.BoolProperty(name='Use MainTex As Mask', description='用折射量当色差遮罩:打开后色差只出现在折射偏移大的地方,没有折射的地方不出现。\n_UseMainTexAsMask', default=False, update=kit.writer(stack, '_UseMainTexAsMask'))
    a['p_SaturationValue'] = bpy.props.FloatProperty(name='Saturation', description='折射后画面的饱和度(0 – 2):1 不变,0 = 灰度,大于 1 更艳。\n_SaturationValue', default=1.0, min=0.0, max=2.0, update=kit.writer(stack, '_SaturationValue'))
    a['p_ColorBlendIntensity'] = bpy.props.FloatProperty(name='Color Blend Intensity', description='折射后画面混入「颜色渐变图」的比例(0 – 1):0 = 不混,1 = 完全换成渐变图查出的颜色。\n_ColorBlendIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_ColorBlendIntensity'))
    a['p_ColorIntensity'] = bpy.props.FloatProperty(name='Color Intensity', description='颜色渐变图的亮度倍率。\n_ColorIntensity', default=1.0, update=kit.writer(stack, '_ColorIntensity'))
    a['p_SpreadUVSpeed'] = bpy.props.FloatVectorProperty(name='Spread UV Speed', description='扩散图的 UV 滚动速度(UV 单位,只用前两个数,按时间滚动)。\nX: 沿 U 每秒滚动多少。\nY: 沿 V 每秒滚动多少。\nZ: 没有用到。\nW: 没有用到。\n_SpreadUVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_SpreadUVSpeed'))
    a['p_SpreadUVRotate'] = bpy.props.FloatProperty(name='Spread UV Rotate (度)', description='扩散图的 UV 旋转角度(度)。\n_SpreadUVRotate', default=0.0, update=kit.writer(stack, '_SpreadUVRotate'))
    a['p_SpreadScheduleOffset'] = bpy.props.FloatProperty(name='Spread Schedule Offset', description='扩散进度:往上调特效从扩散图较暗的地方向亮的地方逐渐出现(粒子的第一套 UV 的 W 分量也会加进进度),做扩散动画就是给它打关键帧。\n_SpreadScheduleOffset', default=0.0, update=kit.writer(stack, '_SpreadScheduleOffset'))
    a['p_SpreadRange'] = bpy.props.FloatProperty(name='Spread Range', description='扩散的过渡宽度:越大扩散的边缘越宽越柔,越小越硬。\n_SpreadRange', default=1.0, update=kit.writer(stack, '_SpreadRange'))
    a['p_SpreadFlip'] = bpy.props.BoolProperty(name='Spread Flip', description='翻转扩散:打开后先出现扩散图较亮的地方,而不是较暗的地方。\n_SpreadFlip', default=False, update=kit.writer(stack, '_SpreadFlip'))
    a['p_SpreadAlphaCurve'] = bpy.props.FloatProperty(name='Spread Alpha Curve', description='扩散结果的不透明度倍率:越大扩散出现的区域越实。\n_SpreadAlphaCurve', default=1.0, update=kit.writer(stack, '_SpreadAlphaCurve'))
    a['p_RadialBlurIntensity'] = bpy.props.FloatProperty(name='Radial Blur Intensity', description='径向模糊强度:从屏幕中心向外拉出放射状模糊的程度,越大越糊,0 = 没有模糊(粒子顶点透明度也会乘进去)。\n_RadialBlurIntensity', default=0.0, update=kit.writer(stack, '_RadialBlurIntensity'))
