    a['p_CanterOffset'] = bpy.props.FloatVectorProperty(name='Radial Blur Center Offset', description='径向模糊中心的偏移(只用前两个数):把模糊的中心从屏幕正中挪开一点。\nX: 中心向右挪多少(屏幕宽的比例)。\nY: 中心向上挪多少(屏幕高的比例)。\nZ: 没有用到。\nW: 没有用到。\n_CanterOffset', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_CanterOffset'))
    a['p_FocusScreenCenterInnerSize'] = bpy.props.FloatProperty(name='Focus Screen Center Inner Size', description='聚焦屏幕中心的内圈尺寸:屏幕中心这么大范围内描边完全不显示,用来把注意力留给屏幕中央。\n_FocusScreenCenterInnerSize', default=0.0, update=kit.writer(stack, '_FocusScreenCenterInnerSize'))
    a['p_FocusScreenCenterOuterRange'] = bpy.props.FloatProperty(name='Focus Screen Center Outer Range', description='聚焦屏幕中心的外圈范围:从内圈到外圈描边逐渐显现,越大渐变越缓。\n_FocusScreenCenterOuterRange', default=1.0, update=kit.writer(stack, '_FocusScreenCenterOuterRange'))
    a['p_BaseColor'] = bpy.props.FloatVectorProperty(name='Base Color', description='基础颜色(HDR):乘在基础颜色图上,可以超过 1 做出发光。\nA: 整体透明度系数。\n_BaseColor', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_BaseColor'))
    a['p_IndirectColor'] = bpy.props.FloatVectorProperty(name='Indirect Color', description='背光色(HDR,雾块):雾块背对主光时的颜色,与受光色按「Light Factor」混合。\n_IndirectColor', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(0.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_IndirectColor'))
    a['p_CustomLightDir'] = bpy.props.FloatVectorProperty(name='Custom Light Dir (xyz 方向, w 启用)', description='自定义光方向:XYZ 是方向,W 是启用比例。启用后光照按面片自己的切线空间计算,不再用场景主光。\nX: 光方向的 X 分量(切线空间,面片的右)。\nY: 光方向的 Y 分量(切线空间,面片的上)。\nZ: 光方向的 Z 分量(切线空间,面片法线方向)。\nW: 启用比例:0 = 用场景主光,1 = 用这个方向,中间值混合。\n_CustomLightDir', size=4, default=(0.0, 0.0, 1.0, 0.0,), update=kit.writer(stack, '_CustomLightDir'))
    a['p_BaseAlphaIntensity'] = bpy.props.FloatProperty(name='Base Alpha Intensity', description='基础不透明度倍率(0 – 10,雾块):乘在最终不透明度上,大于 1 让淡雾更实,结果仍限制在 1 以内。\n_BaseAlphaIntensity', default=1.0, min=0.0, max=10.0, update=kit.writer(stack, '_BaseAlphaIntensity'))
    a['p_FogNoiseIntensity'] = bpy.props.FloatProperty(name='Fog Noise Intensity', description='雾噪声强度(0 – 1):雾的不透明度被噪声图(R 通道)调制的程度,0 = 均匀不调制,1 = 完全按噪声图。\n_FogNoiseIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_FogNoiseIntensity'))
    a['p_UseWind'] = bpy.props.FloatProperty(name='Use Wind', description='风开关:0 = 关,1 = 用滚动的噪声(风)给雾块的明暗做流动变化。\n_UseWind', default=0.0, update=kit.writer(stack, '_UseWind'))
    a['p_WindNoiseIntensity'] = bpy.props.FloatProperty(name='Wind Noise Intensity', description='风噪声强度(0 – 1):风造成的明暗起伏幅度,0 = 无起伏。\n_WindNoiseIntensity', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WindNoiseIntensity'))
    a['p_WindNoiseContrast'] = bpy.props.FloatProperty(name='Wind Noise Contrast', description='风噪声对比度(−5 – 5):调高让流动的明暗更分明,0 = 默认,负值让对比变弱甚至反相。\n_WindNoiseContrast', default=0.0, min=-5.0, max=5.0, update=kit.writer(stack, '_WindNoiseContrast'))
    a['p_WindScale'] = bpy.props.FloatProperty(name='Wind Scale', description='风噪声的整体平铺(0 – 1):数值越大噪声图案越细碎。\n_WindScale', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WindScale'))
    a['p_UseSeparateScale'] = bpy.props.BoolProperty(name='Use Separate Scale', description='分别设置风的横纵平铺:打开后在「Wind Scale」基础上再分别乘下面的 X、Y 值,关闭则只用「Wind Scale」。\n_UseSeparateScale', default=False, update=kit.writer(stack, '_UseSeparateScale'))
    a['p_WindScaleX'] = bpy.props.FloatProperty(name='Wind Scale X', description='风噪声横向平铺倍率(0 – 1):需要打开「Use Separate Scale」,与「Wind Scale」相乘。\n_WindScaleX', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WindScaleX'))
    a['p_WindScaleY'] = bpy.props.FloatProperty(name='Wind Scale Y', description='风噪声纵向平铺倍率(0 – 1):需要打开「Use Separate Scale」,与「Wind Scale」相乘。\n_WindScaleY', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WindScaleY'))
    a['p_WindDirX'] = bpy.props.FloatProperty(name='Wind Dir X', description='风的流动方向 X 分量(−1 – 1):正负决定左右,绝对值乘进流动快慢。\n_WindDirX', default=1.0, min=-1.0, max=1.0, update=kit.writer(stack, '_WindDirX'))
    a['p_WindDirY'] = bpy.props.FloatProperty(name='Wind Dir Y', description='风的流动方向 Y 分量(−1 – 1):正负决定上下,绝对值乘进流动快慢。\n_WindDirY', default=1.0, min=-1.0, max=1.0, update=kit.writer(stack, '_WindDirY'))
    a['p_WindSpeed'] = bpy.props.FloatProperty(name='Wind Speed', description='风噪声的流动速度(0 – 1):0 = 不流动。\n_WindSpeed', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_WindSpeed'))
    a['p_UseNormalTex'] = bpy.props.BoolProperty(name='Use Normal Tex', description='使用法线图:打开后用「Normal Tex」做光照明暗,关闭则整块雾面按平面法线着色、没有起伏。\n_UseNormalTex', default=False, update=kit.writer(stack, '_UseNormalTex'))
    a['p_TwoSidedNormal'] = bpy.props.BoolProperty(name='Two Sided Normal', description='双面法线:打开后背面的法线翻转,雾块从背面看光照也正确。\n_TwoSidedNormal', default=False, update=kit.writer(stack, '_TwoSidedNormal'))
    a['p_LightFactor'] = bpy.props.FloatProperty(name='Light Factor', description='受光程度(0 – 1):0 = 完全不受主光影响(一直是受光色),1 = 完全按光照明暗(背光处变成「Indirect Color」)。\n_LightFactor', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_LightFactor'))
    a['p_UseFresnel'] = bpy.props.FloatProperty(name='Use Fresnel', description='菲涅尔开关:打开后按视角调整雾块的颜色与不透明度(强度见「Fresnel Intensity」)。\n_UseFresnel', default=0.0, update=kit.writer(stack, '_UseFresnel'))
    a['p_FlipFresnel'] = bpy.props.BoolProperty(name='Flip Fresnel', description='翻转菲涅尔:开 = 正对相机处保持、边缘变淡;关 = 边缘保持、正对相机处变淡。\n_FlipFresnel', default=True, update=kit.writer(stack, '_FlipFresnel'))
    a['p_FresnelIntensity'] = bpy.props.FloatProperty(name='Fresnel Intensity', description='菲涅尔强度(0 – 1):0 = 不起作用,1 = 完全按菲涅尔衰减。\n_FresnelIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_FresnelIntensity'))
    a['p_FresnelContract'] = bpy.props.FloatProperty(name='Fresnel Contract', description='菲涅尔对比(0.01 – 10,指数):越大衰减范围越集中、过渡越陡。\n_FresnelContract', default=1.0, min=0.01, max=10.0, update=kit.writer(stack, '_FresnelContract'))
    a['p_TopFadeContract'] = bpy.props.FloatProperty(name='Top Fade Contract', description='顶部淡出速度(0 – 10):物体原点以上每升高一个物体高度,不透明度下降这么多;0 = 不淡出。\n_TopFadeContract', default=0.0, min=0.0, max=10.0, update=kit.writer(stack, '_TopFadeContract'))
    a['p_TopFadeOffset'] = bpy.props.FloatProperty(name='Top Fade Offset', description='顶部淡出的基准(−1 – 1):默认 1 = 物体原点处完全不透明;调低则原点以上更早开始变透明。\n_TopFadeOffset', default=1.0, min=-1.0, max=1.0, update=kit.writer(stack, '_TopFadeOffset'))
    a['p_NormalMapUVSpeed'] = bpy.props.FloatVectorProperty(name='NormalMap UV Speed', description='法线图的 UV 滚动速度(UV 单位)。前两个数按时间滚动,后两个数按粒子自定义数据滚动。\nX: 按时间沿 U 滚动:每秒滚动多少。\nY: 按时间沿 V 滚动:每秒滚动多少。\nZ: 按粒子自定义数据沿 U 滚动。\nW: 按粒子自定义数据沿 V 滚动。\n_NormalMapUVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_NormalMapUVSpeed'))
    a['p_NormalMapUVRotateMat'] = bpy.props.FloatVectorProperty(name='NormalMap UV Rotate Mat', description='法线图的 UV 旋转:四个数是 2×2 旋转矩阵,要转 θ 度就填 (cosθ, sinθ, −sinθ, cosθ);默认 (1, 0, 0, 1) = 不旋转。\nX: 新 U 里 U 的系数(旋转时 = cosθ)。\nY: 新 V 里 U 的系数(旋转时 = sinθ)。\nZ: 新 U 里 V 的系数(旋转时 = −sinθ)。\nW: 新 V 里 V 的系数(旋转时 = cosθ)。\n_NormalMapUVRotateMat', size=4, default=(1.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_NormalMapUVRotateMat'))
