    a['p_MaskTexUVRotate'] = bpy.props.FloatProperty(name='MaskTex UV Rotate (度)', description='遮罩图的 UV 旋转角度(度)。\n_MaskTexUVRotate', default=0.0, update=kit.writer(stack, '_MaskTexUVRotate'))
