    a['p_UseMaskTexAsAlpha'] = bpy.props.BoolProperty(name='MaskTex As Alpha', description='遮罩 R 通道当透明度:打开后遮罩只用 R 决定显示范围,不改变颜色;关闭则用遮罩的 A 当透明度,并让遮罩的颜色也乘到特效上。\n_UseMaskTexAsAlpha', default=False, update=kit.writer(stack, '_UseMaskTexAsAlpha'))
    a['p_Color'] = bpy.props.FloatVectorProperty(name='Smoke Color', description='烟雾的颜色:乘在顶点色上(顶点色里画的颜色深浅会保留)。\n_Color', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_Color'))
