    a['p_FresnelColor'] = bpy.props.FloatVectorProperty(name='Fresnel Color (w = 覆盖量)', description='菲涅尔颜色(HDR):特效在边缘(或翻转后的中间)染成这个颜色。\nA: 覆盖量:染色的比例,0 = 不染。\n_FresnelColor', size=4, subtype='COLOR_GAMMA', min=0.0, soft_max=1.0, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_FresnelColor'))
