    a['p_SampleTex4UVSpeed'] = bpy.props.FloatVectorProperty(name='SampleTex4 UV Speed', description='第 4 层取样图的 UV 滚动速度(UV 单位,只用前两个数,按时间滚动)。\nX: 沿 U(横向)每秒滚动多少,正负决定方向。\nY: 沿 V(纵向)每秒滚动多少,正负决定方向。\nZ: 没有用到。\nW: 没有用到。\n_SampleTex4UVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_SampleTex4UVSpeed'))
