    a['p_SampleTex4UseWeight4'] = bpy.props.FloatProperty(name='SampleTex4 → 叠色', description='第 4 层当「叠色」用的比例:0 = 不参与,1 = 完全参与;参与叠色的层按「Blend Tint」染色后加到特效上。\n_SampleTex4UseWeight4', default=0.0, update=kit.writer(stack, '_SampleTex4UseWeight4'))
    a['p_SampleTex4UseWeight5'] = bpy.props.FloatProperty(name='SampleTex4 → 溶解排程', description='第 4 层当「溶解排程」用的比例:0 = 不参与,1 = 完全参与;这层图的 R 通道决定溶解的先后顺序(越暗越先消失,需要打开「Use Dissolve」)。\n_SampleTex4UseWeight5', default=0.0, update=kit.writer(stack, '_SampleTex4UseWeight5'))
