    a['p_UseSampleTex5AsAlpha'] = bpy.props.BoolProperty(name='SampleTex5 As Alpha', description='第 5 层只读 R 通道:打开后这一层只用取样图的 R(灰度)当不透明度,颜色一律按白处理;适合灰度的遮罩、噪声图。\n_UseSampleTex5AsAlpha', default=False, update=kit.writer(stack, '_UseSampleTex5AsAlpha'))
    a['p_SampleTex5MipmapBias'] = bpy.props.FloatProperty(name='SampleTex5 Mipmap Bias', description='第 5 层的细节层级偏移:游戏里用来让这一层更清晰或更模糊,Blender 里没有对应的口,改它不会改变画面。\n_SampleTex5MipmapBias', default=0.0, update=kit.writer(stack, '_SampleTex5MipmapBias'))
    a['p_SampleTex5UVSpeed'] = bpy.props.FloatVectorProperty(name='SampleTex5 UV Speed', description='第 5 层取样图的 UV 滚动速度(UV 单位,只用前两个数,按时间滚动)。\nX: 沿 U(横向)每秒滚动多少,正负决定方向。\nY: 沿 V(纵向)每秒滚动多少,正负决定方向。\nZ: 没有用到。\nW: 没有用到。\n_SampleTex5UVSpeed', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_SampleTex5UVSpeed'))
    a['p_SampleTex5UseWeight0'] = bpy.props.FloatProperty(name='SampleTex5 → 扰动', description='第 5 层当「扰动」用的比例:0 = 不参与扰动,1 = 完全参与;参与扰动的层会把主图的 UV 推歪(需要打开「Use Disturb」)。\n_SampleTex5UseWeight0', default=0.0, update=kit.writer(stack, '_SampleTex5UseWeight0'))
