    a['p_ConeParams0'] = bpy.props.FloatVectorProperty(name='Cone Params 0 (xy 起止半径, zw 锥坡 cos/sin)', description='体积光束的锥形参数:前两个数是起点与远端的半径,后两个数是锥面斜率(光束侧面法线用)。\nX: 光束起点(光源端)的半径(物体空间)。\nY: 光束远端的半径(物体空间)。\nZ: 锥坡的 cos:光束侧面法线的水平分量。\nW: 锥坡的 sin:光束侧面法线沿轴的分量。\n_ConeParams0', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_ConeParams0'))
    a['p_ConeParams1'] = bpy.props.FloatVectorProperty(name='Cone Params 1 (xyz 本地前向, w 画端盖)', description='体积光束的朝向与端盖:XYZ 是光束沿本地的前进方向(决定倾斜与视线夹角),W 决定是否画端盖。\nX: 光束前进方向的 X 分量(本地空间)。\nY: 光束前进方向的 Y 分量(本地空间)。\nZ: 光束前进方向的 Z 分量(本地空间)。\nW: 画端盖:1 = 光束两头封口,0 = 不画端盖。\n_ConeParams1', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_ConeParams1'))
    a['p_DistanceFallOff'] = bpy.props.FloatVectorProperty(name='Distance Fall Off (x 起, y 止, z 几何长度, w 起点渐入)', description='体积光束沿轴的距离衰减:从起点到终点光束由满强度渐变到消失,并带光源端渐入。\nX: 衰减起点(离光源的距离):近于它不衰减。\nY: 衰减终点(离光源的距离):远于它光束完全消失。\nZ: 光束的几何长度:把单位锥网格拉到实际长度。\nW: 光源端渐入距离:离光源这么远之内光束由透明渐变到不透明。\n_DistanceFallOff', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_DistanceFallOff'))
    a['p_TiltVectorX'] = bpy.props.FloatProperty(name='Tilt Vector X', description='光束倾斜校正 X:把横向位置按这个系数计入离光源的距离,倾斜的光束用它让衰减沿倾斜方向走。\n_TiltVectorX', default=0.0, update=kit.writer(stack, '_TiltVectorX'))
    a['p_TiltVectorY'] = bpy.props.FloatProperty(name='Tilt Vector Y', description='光束倾斜校正 Y:把纵向位置按这个系数计入离光源的距离,倾斜的光束用它让衰减沿倾斜方向走。\n_TiltVectorY', default=0.0, update=kit.writer(stack, '_TiltVectorY'))
    a['p_ConeGeomProps'] = bpy.props.FloatProperty(name='Cone Geom Props (虚顶点沿轴的偏移)', description='锥顶虚拟顶点沿轴的偏移:计算边缘光方向时,把光束的锥顶沿轴向前或向后挪这么远。\n_ConeGeomProps', default=0.0, update=kit.writer(stack, '_ConeGeomProps'))
    a['p_ColorFlat'] = bpy.props.FloatVectorProperty(name='Color', description='光束颜色:RGB 是光束的颜色,A 乘进不透明度。\n_ColorFlat', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_ColorFlat'))
    a['p_AlphaInside'] = bpy.props.FloatProperty(name='Alpha Inside', description='光束不透明度倍率之一:光束分两层壳,标志为 0 的面用「Alpha Inside」,标志为 1 的面用「Alpha Outside」,调两者即分别调两层壳的浓度。\n_AlphaInside', default=1.0, update=kit.writer(stack, '_AlphaInside'))
    a['p_AlphaOutside'] = bpy.props.FloatProperty(name='Alpha Outside', description='光束不透明度倍率之二:光束分两层壳,标志为 1 的面用「Alpha Outside」,标志为 0 的面用「Alpha Inside」。\n_AlphaOutside', default=1.0, update=kit.writer(stack, '_AlphaOutside'))
    a['p_DistanceCamClipping'] = bpy.props.FloatProperty(name='Camera Clipping Distance', description='相机近处裁切淡出距离:从相机近裁剪面起,这个距离内光束由透明渐变到不透明,避免相机穿过光束时突然出现大块色块。\n_DistanceCamClipping', default=0.5, update=kit.writer(stack, '_DistanceCamClipping'))
    a['p_DistanceFadeStart'] = bpy.props.FloatProperty(name='Distance Fade Start', description='按到相机距离淡入的起点(0.001 – 3000,体积光束与雾块共用):近于它完全透明。\n_DistanceFadeStart', default=0.001, min=0.001, max=3000.0, update=kit.writer(stack, '_DistanceFadeStart'))
    a['p_DistanceFadeEnd'] = bpy.props.FloatProperty(name='Distance Fade End', description='按到相机距离淡入的终点(0.001 – 3000,体积光束与雾块共用):远于它不再淡出,中间线性过渡。\n_DistanceFadeEnd', default=0.001, min=0.001, max=3000.0, update=kit.writer(stack, '_DistanceFadeEnd'))
    a['p_DistanceFadeStartSecond'] = bpy.props.FloatProperty(name='Distance Fade Start Second', description='第二组距离淡入的起点(0.001 – 3000):与第一组相乘,近于它完全透明;两组配合可以做出只在一段距离内可见的光束。\n_DistanceFadeStartSecond', default=0.001, min=0.001, max=3000.0, update=kit.writer(stack, '_DistanceFadeStartSecond'))
    a['p_DistanceFadeEndSecond'] = bpy.props.FloatProperty(name='Distance Fade End Second', description='第二组距离淡入的终点(0.001 – 3000):远于它不再淡出,与第一组相乘。\n_DistanceFadeEndSecond', default=0.001, min=0.001, max=3000.0, update=kit.writer(stack, '_DistanceFadeEndSecond'))
    a['p_AttenuationLerpLinearQuad'] = bpy.props.FloatProperty(name='Lerp between attenuation linear and quad', description='衰减曲线混合(体积光束):0 = 沿光束平滑渐隐,1 = 二次衰减(亮度集中在光源附近,末端急收);中间值混合。\n_AttenuationLerpLinearQuad', default=0.5, update=kit.writer(stack, '_AttenuationLerpLinearQuad'))
    a['p_DepthBlendDistance'] = bpy.props.FloatProperty(name='Depth Blend Distance', description='光束与场景几何的软交界距离(世界单位):光束靠近不透明物体表面这个距离内逐渐淡出,避免硬切;0 = 不做。需要打开深度混合。\n_DepthBlendDistance', default=2.0, update=kit.writer(stack, '_DepthBlendDistance'))
    a['p_DepthBlendCapOff'] = bpy.props.BoolProperty(name='Depth Blend Cap Off', description='光源附近不做软交界:打开后靠近光源的一段不做深度混合,离光源越远越逐渐生效。\n_DepthBlendCapOff', default=False, update=kit.writer(stack, '_DepthBlendCapOff'))
    a['p_FresnelPow'] = bpy.props.FloatProperty(name='Fresnel Pow', description='光束边缘光指数(0 – 15):越大光束中心越亮、边缘越淡,轮廓越柔;越小光束越均匀。\n_FresnelPow', default=1.0, min=0.0, max=15.0, update=kit.writer(stack, '_FresnelPow'))
    a['p_GlareFrontal'] = bpy.props.FloatProperty(name='Glare Frontal', description='迎面眩光(0 – 1):沿光束轴向看光束时,数值越大边缘光指数被压得越低,光束越均匀越亮;视线偏离光束轴时不起作用。\n_GlareFrontal', default=0.5, min=0.0, max=1.0, update=kit.writer(stack, '_GlareFrontal'))
    a['p_GlareBehind'] = bpy.props.FloatProperty(name='Glare from Behind', description='背面眩光(0 – 1):光束内层壳沿光束轴向看时使用,数值越大边缘光指数被压得越低,光束越均匀越亮。\n_GlareBehind', default=0.5, min=0.0, max=1.0, update=kit.writer(stack, '_GlareBehind'))
    a['p_UseClippingPlane'] = bpy.props.BoolProperty(name='Use Clipping Plane', description='使用附加切平面:打开后光束只保留切平面法线所指的一侧,切口按「Clipping Plane Transition」渐变。\n_UseClippingPlane', default=False, update=kit.writer(stack, '_UseClippingPlane'))
    a['p_AdditionalClippingPlaneWS'] = bpy.props.FloatVectorProperty(name='Additional Clipping Plane WS', description='附加切平面(世界空间):平面方程 n·p + w = 0,法线所指的一侧保留。\nX: 平面法线的 X 分量。\nY: 平面法线的 Y 分量。\nZ: 平面法线的 Z 分量。\nW: 平面常数 w:平面离原点的偏移,沿法线反方向为正。\n_AdditionalClippingPlaneWS', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_AdditionalClippingPlaneWS'))
    a['p_ClippingPlaneTransition'] = bpy.props.FloatProperty(name='Clipping Plane Transition', description='切平面渐变宽度(0.01 – 10,世界单位):离切平面这个距离内光束由透明渐变到不透明。\n_ClippingPlaneTransition', default=1.0, min=0.01, max=10.0, update=kit.writer(stack, '_ClippingPlaneTransition'))
    a['p_ScanLinePlane'] = bpy.props.FloatVectorProperty(name='扫描平面(xyz 法线, w 距离)', description='技能扫描线的平面:由技能逻辑写入,一般不用手调。\nX: 平面法线的 X 分量。\nY: 平面法线的 Y 分量。\nZ: 平面法线的 Z 分量。\nW: 平面到原点的距离。\n_ScanLinePlane', size=4, default=(0.0, 1.0, 0.0, 0.0,), update=kit.writer(stack, '_ScanLinePlane'))
    a['p_ScanLineColor'] = bpy.props.FloatVectorProperty(name='扫描线色', description='技能扫描线的颜色(HDR)。\n_ScanLineColor', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_ScanLineColor'))
    a['p_BlackBoxColor'] = bpy.props.FloatVectorProperty(name='黑箱轮廓色', description='黑箱轮廓的颜色(HDR)。\n_BlackBoxColor', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_BlackBoxColor'))
    a['p_GridLineWidth'] = bpy.props.FloatProperty(name='Grid Line Width', description='网格线的宽度:线特效叠在表面上的网格线的粗细,越大越粗,0 = 没有网格线。\n_GridLineWidth', default=1.0, min=0.1, max=15.0, update=kit.writer(stack, '_GridLineWidth'))
    a['p_EnableDepthOnlyDither'] = bpy.props.BoolProperty(name='深度趟抖动', description='深度趟抖动:打开后写深度的那一趟也按透明度用屏幕网点裁剪,让半透明部分的深度更准确。\n_EnableDepthOnlyDither', default=False, update=kit.writer(stack, '_EnableDepthOnlyDither'))
    a['p_TaaFrameInfo'] = bpy.props.FloatVectorProperty(name='TAA Frame Info', description='引擎全局的抗锯齿帧信息,由引擎自动写入,不用手调。\nX: 没有用到。\nY: 没有用到。\nZ: 本帧的抖动相位,用来让屏幕网点逐帧错开。\nW: 本帧的抖动相位(与 Z 相同)。\n_TaaFrameInfo', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_TaaFrameInfo'))
    a['p_TransparentMatColor'] = bpy.props.FloatVectorProperty(name='穿墙材质色', description='透视材质的颜色(HDR):用来把被遮挡的角色用一种统一的颜色显示出来(穿墙可见)。\n_TransparentMatColor', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_TransparentMatColor'))
    a['p_UseVFXPortal'] = bpy.props.BoolProperty(name='VFX Portal', description='传送门模式:打开后不透明度不足「Portal Alpha」的像素被直接丢掉,配合模板做出传送门、遮罩窗口那类「只在某个形状里显示」的效果。\n_UseVFXPortal', default=False, update=kit.writer(stack, '_UseVFXPortal'))
