    a['p_UseSludge'] = bpy.props.BoolProperty(name='Use Sludge', description='淤泥范围开关:用一张高度图按物体在「淤泥坐标系」里的位置限制特效的可见范围,做出地面上被污染、侵蚀的一片区域。\n_UseSludge', default=False, update=kit.writer(stack, '_UseSludge'))
    a['p_SludgeHeightTextureParams0'] = bpy.props.FloatVectorProperty(name='Sludge Params0 (xyz 原点, w 范围)', description='淤泥坐标系的原点与范围。\nX: 坐标系原点的世界 X。\nY: 坐标系原点的世界 Y。\nZ: 坐标系原点的世界 Z。\nW: 沿两条轴方向能走多远(米),超过的位置按边界处理。\n_SludgeHeightTextureParams0', size=4, default=(0.0, 0.0, 0.0, 0.0,), update=kit.writer(stack, '_SludgeHeightTextureParams0'))
