    a['p_SequenceBaseColorMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='序列帧颜色图', description='序列帧颜色图(水面):一张按「Sequence Frame Size」行列数切格的图集,随时间逐格播放;颜色按「序列帧颜色图色相」染色后叠到水面颜色上,A 通道是序列帧自己的不透明度。\nR: 序列帧颜色的红分量。\nG: 序列帧颜色的绿分量。\nB: 序列帧颜色的蓝分量。\nA: 序列帧的不透明度:同时乘进水面不透明度与次表面强度。\n_SequenceBaseColorMap', update=kit.image_writer(stack, '_SequenceBaseColorMap'))
    a['p_SequenceMotionVectorMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='序列帧Motion Vector图', description='序列帧运动向量图(非颜色数据):记录相邻两帧之间每个像素往哪边移动,播放时据此在帧与帧之间插值,低帧率的序列帧也能顺滑;推的距离由「Motion Vector Distortion Strength」决定。\nR: 横向移动方向(0.5 灰 = 不动,大于 0.5 往正方向)。\nG: 纵向移动方向(0.5 灰 = 不动,大于 0.5 往正方向)。\n_SequenceMotionVectorMap', update=kit.image_writer(stack, '_SequenceMotionVectorMap'))
    a['p_SequenceNormalMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='序列帧法线图', description='序列帧法线图(非颜色数据):与颜色图同格同步播放的法线,打开后取代水面原来的法线,让水面起伏跟着序列帧变化;强度由「序列帧法线图Scale」决定。\nR: 法线 X 方向(切线空间,0.5 灰 = 不偏)。\nG: 法线 Y 方向(切线空间,0.5 灰 = 不偏)。\n_SequenceNormalMap', update=kit.image_writer(stack, '_SequenceNormalMap'))
    a['p_DissolveTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Dissolve Tex', description='溶解噪声图(非颜色数据):只读 R 通道,和当前溶解进度比较,越暗的地方越先消失,图案的明暗分布决定溶解的形状。\nR: 溶解先后:越暗越先消失,其余通道不读。\n_DissolveTex', update=kit.image_writer(stack, '_DissolveTex'))
    a['t_DissolveTex'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), description='贴图平铺:图案在 UV 上横向、纵向各重复几次,1 = 铺满一次,2 = 重复两次。\n_DissolveTex_ST.xy', update=kit.st_writer(stack, '_DissolveTex'))
    a['o_DissolveTex'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), description='贴图偏移:图案在 UV 上整体平移多少,单位是 UV(1 = 平移一整张图)。\n_DissolveTex_ST.zw', update=kit.st_writer(stack, '_DissolveTex'))
    a['p_RefractTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Refract Tex', description='折射图(非颜色数据):决定后面的画面被推歪的方向和量。普通模式读 R 通道,法线模式读 A 与 G 通道。\nR: 普通模式下折射的量:0 不推,1 推到最大。\nG: 法线模式下的纵向偏移。\nA: 法线模式下的横向偏移。\n_RefractTex', update=kit.image_writer(stack, '_RefractTex'))
    a['t_RefractTex'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), description='贴图平铺:图案在 UV 上横向、纵向各重复几次,1 = 铺满一次,2 = 重复两次。\n_RefractTex_ST.xy', update=kit.st_writer(stack, '_RefractTex'))
    a['o_RefractTex'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), description='贴图偏移:图案在 UV 上整体平移多少,单位是 UV(1 = 平移一整张图)。\n_RefractTex_ST.zw', update=kit.st_writer(stack, '_RefractTex'))
    a['p_RainTex0'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Rain Tex 0', description='雨图(雨特效):只读 R 通道当雨条的形状,按粒子 UV 平铺采样,平铺倍数由「RainTex0 Tiling/Offset」的 X、Y 决定。\nR: 雨条形状:以 0.5 为中心,亮于 0.5 的地方雨更浓,暗于 0.5 的地方雨更淡。\n_RainTex0', update=kit.image_writer(stack, '_RainTex0'))
    a['t_RainTex0'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), description='贴图平铺:图案在 UV 上横向、纵向各重复几次,1 = 铺满一次,2 = 重复两次。\n_RainTex0_ST.xy', update=kit.st_writer(stack, '_RainTex0'))
    a['o_RainTex0'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), description='贴图偏移:图案在 UV 上整体平移多少,单位是 UV(1 = 平移一整张图)。\n_RainTex0_ST.zw', update=kit.st_writer(stack, '_RainTex0'))
    a['p_PositiveAxesLightmap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Six-Way +Axes Lightmap', description='六向光照图 +轴(非颜色数据,六向烟雾用):R、G、B 分别是烟雾被来自 +X、+Y、+Z 方向的光照亮时的亮度,按太阳与环境光的方向混合出明暗;A 同时乘进最终不透明度。要和「−轴」那张配对使用。\nR: +X 方向来光时的亮度(X 轴 = 面片的切线方向)。\nG: +Y 方向来光时的亮度(Y 轴 = 垂直于切线与视线的方向)。\nB: +Z 方向来光时的亮度(Z 轴 = 朝向相机的方向)。\nA: 整体不透明度:乘到最终不透明度上,白 = 不影响。\n_PositiveAxesLightmap', update=kit.image_writer(stack, '_PositiveAxesLightmap'))
    a['p_NegativeAxesLightmap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Six-Way -Axes Lightmap', description='六向光照图 −轴(非颜色数据,六向烟雾用):R、G、B 分别是烟雾被来自 −X、−Y、−Z 方向的光照亮时的亮度,与「+轴」那张配对使用;A 当作自发光色带的取样位置。\nR: −X 方向来光时的亮度。\nG: −Y 方向来光时的亮度。\nB: −Z 方向来光时的亮度。\nA: 自发光色带的取样位置(只在打开「Use Emissive Ramp」时使用)。\n_NegativeAxesLightmap', update=kit.image_writer(stack, '_NegativeAxesLightmap'))
    return a


